"""Self-contained local workbench. No remote resources or implicit computation."""
from __future__ import annotations
import json
import re
from pathlib import Path


def write_workbench_report(bundle: dict, analysis: dict, directory: str | Path) -> Path:
    destination = Path(directory)
    destination.mkdir(parents=True, exist_ok=True)
    assets = Path(__file__).with_name("assets")
    raw_bundle = json.dumps(bundle, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    raw_analysis = json.dumps(analysis, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    def safe(value: str) -> str:
        return value.replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    replacements = {
        "__CSS__": (assets / "workbench.css").read_text(encoding="utf-8"),
        "__JS__": (assets / "workbench.js").read_text(encoding="utf-8"),
        "__BUNDLE__": safe(raw_bundle),
        "__ANALYSIS__": safe(raw_analysis),
    }
    page = re.sub(r"__(?:CSS|JS|BUNDLE|ANALYSIS)__", lambda match: replacements[match.group()], _HTML)
    for name, content in (("data.json", raw_bundle), ("analysis.json", raw_analysis), ("index.html", page)):
        temporary = destination / (name + ".tmp")
        temporary.write_text(content, encoding="utf-8")
        temporary.replace(destination / name)
    return destination / "index.html"


